import {validateInheritance} from './breeding-inheritance.js?v=0.90.18';
import {DATA} from './data.js?v=0.87.0';
import {rootForm} from './route-roster.js?v=0.87.0';
import {validateNurserySnapshot} from './breeding.js?v=0.90.18';
import {PALADIN_IDS} from './paladin-data.js?v=0.87.0';
export const SAVE_FILE_FORMAT='abyssals-expedition';
export const SAVE_FILE_VERSION=1;
export const SAVE_FILE_LIMIT=5*1024*1024;
export const SAVE_GAME_VERSION='0.90.19';
const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const fail=message=>{throw new Error(message);};
function inspect(value,depth=0,budget={left:200000}){if(--budget.left<0||depth>80)fail('This save file is too complex.');if(typeof value==='number'&&!Number.isFinite(value))fail('The save contains an invalid number.');if(value&&typeof value==='object')for(const [key,v]of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(key))fail('The save contains an unsupported field.');inspect(v,depth+1,budget);}}
export function validateTransferSnapshot(snapshot,{speciesIds,moveIds,rooms,stateTemplate}={}){
 inspect(snapshot);if(!object(snapshot)||snapshot.version!==1||!object(snapshot.state))fail('This is not a supported Abyssals save.');const s=snapshot.state;
 if(s.begun!==true||typeof s.playerName!=='string'||s.playerName.length>120||!Number.isFinite(s.money)||s.money<0)fail('The expedition details are incomplete.');
 if(!Array.isArray(s.party)||s.party.length>6||!Array.isArray(s.reserve)||!Array.isArray(s.dead)||s.reserve.length+s.dead.length>2000)fail('The partner records are incomplete.');
 if(stateTemplate)for(const [key,example]of Object.entries(stateTemplate)){const value=s[key];if(value===undefined||example===null)continue;if(Array.isArray(example)?!Array.isArray(value):object(example)?!object(value):typeof value!==typeof example)fail('The expedition field '+key+' is invalid.');}
 const unit=u=>{if(!object(u)||typeof u.uid!=='string'||!u.uid.length||u.uid.length>300||typeof u.species?.id!=='string')fail('A partner record is invalid.');if(speciesIds&&!speciesIds.has(u.species.id))fail('This save uses an Abyssal unavailable in this build. Update the game first.');if(!Number.isInteger(u.level)||u.level<1||u.level>200||!Number.isFinite(u.hp)||!Number.isFinite(u.maxHp)||u.hp<0||u.maxHp<=0||u.hp>u.maxHp||!object(u.stats)||!Array.isArray(u.moves)||u.moves.length>4)fail('A partner’s level, health or moves are invalid.');for(const stat of ['hp','attack','defence','sp_attack','sp_defence','speed'])if(!Number.isFinite(u.stats[stat])||u.stats[stat]<0)fail('A partner’s stats are invalid.');if(u.stewardship!==undefined&&(!object(u.stewardship)||Object.entries(u.stewardship).some(([k,v])=>!['hp','attack','defence','sp_attack','sp_defence','speed'].includes(k)||!Number.isSafeInteger(v)||v<0)))fail('A stewardship growth record is invalid.');if(u.shiny!==undefined&&typeof u.shiny!=='boolean')fail('A partner’s shiny record is invalid.');if(u.breedingInheritance!==undefined){const born=DATA.species.find(s=>s.id===u.breedingInheritance?.speciesId);if(!born||rootForm(born.id)!==rootForm(u.species.id))fail('A partner’s inherited species is invalid.');validateInheritance(u.breedingInheritance,born);}for(const m of u.moves)if(!object(m)||!Number.isInteger(m.id)||(moveIds&&!moveIds.has(m.id))||(m.left!==undefined&&(!Number.isFinite(m.left)||m.left<0)))fail('This save contains an unavailable or invalid move.');};
 if(s.paladinCourt!==undefined){const q=s.paladinCourt;if(!object(q)||!object(q.roamers)||q.released!==undefined&&typeof q.released!=='boolean')fail('The roaming court record is invalid.');for(const [id,r]of Object.entries(q.roamers)){if(!PALADIN_IDS.includes(id)||!object(r)||!['roaming','captured','killed'].includes(r.status))fail('A roaming guardian record is invalid.');if(r.unit){unit(r.unit);if(r.unit.species.id!==id||r.unit.uid!=='court:'+id||r.status!=='roaming')fail('A roaming guardian identity is invalid.');}}}
 validateNurserySnapshot(s);
 const partners=[...s.party,...s.reserve,...s.dead];partners.forEach(unit);if(new Set(partners.map(u=>u.uid)).size!==partners.length)fail('The save contains duplicate partner identities.');
 if(typeof snapshot.room!=='string'||rooms&&!rooms.has(snapshot.room))fail('This save’s location is unavailable in this build. Update the game first.');const p=snapshot.player;if(!object(p)||!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<0||p.x>=48||p.y<0||p.y>=32||!['up','down','left','right'].includes(p.facing))fail('The saved position is invalid.');
 for(const key of ['phaseElapsed','worldRandom'])if(snapshot[key]!==undefined&&(!Number.isFinite(snapshot[key])||snapshot[key]<0))fail('The expedition clock or random state is invalid.');
 if(snapshot.returnDoor){const d=snapshot.returnDoor;if(!object(d)||!Number.isInteger(d.x)||!Number.isInteger(d.y)||d.x<0||d.x>=48||d.y<0||d.y>=32||(rooms&&!rooms.has(d.room||'town')))fail('The saved return doorway is invalid.');}
 if(snapshot.battle){const b=snapshot.battle;if(!object(b)||b.kind!=='wild'||!Array.isArray(b.enemies)||!b.enemies.length||b.enemies.length>6||!partners.some(u=>u.uid===b.playerUid)||!Number.isInteger(b.randomState)||b.randomState<0||b.randomState>4294967295)fail('The saved battle is incomplete.');if(b.relicDouble!==undefined&&typeof b.relicDouble!=='boolean')fail('The saved double battle flag is invalid.');if(b.relicDouble===true&&!object(b.alliedRivet))fail('The saved double battle is missing its ally.');if(b.finaleDouble){if(b.relicDouble!==true||!Array.isArray(b.activeEnemyIndices)||b.activeEnemyIndices.length!==2||new Set(b.activeEnemyIndices.filter(i=>i>=0)).size!==b.activeEnemyIndices.filter(i=>i>=0).length||b.activeEnemyIndices.some(i=>!Number.isInteger(i)||i< -1||i>=b.enemies.length)||!Number.isInteger(b.reserveCursor)||b.reserveCursor<2||b.reserveCursor>b.enemies.length)fail('The saved finale battle positions are invalid.');}if(b.finaleUnique&&!['guan','fei','crux','gehennuar','suncub'].includes(b.finaleUnique))fail('The saved guardian is invalid.');b.enemies.forEach(unit);if(b.alliedRivet)unit(b.alliedRivet);}
 return snapshot;
}
export function makeSaveFile(snapshot,options={}){validateTransferSnapshot(snapshot,options);return JSON.stringify({format:SAVE_FILE_FORMAT,formatVersion:SAVE_FILE_VERSION,gameVersion:SAVE_GAME_VERSION,exportedAt:new Date().toISOString(),snapshot},null,2);}
export function parseSaveFile(text,options={}){if(typeof text!=='string'||new TextEncoder().encode(text).length>SAVE_FILE_LIMIT)fail('Choose an Abyssals JSON save smaller than 5 MB.');let data;try{data=JSON.parse(text);}catch{fail('This file is not valid JSON. Choose a downloaded Abyssals save.');}inspect(data);let snapshot;if(data?.format===SAVE_FILE_FORMAT){if(data.formatVersion!==SAVE_FILE_VERSION)fail('This save-file version is unsupported. Update the game first.');snapshot=data.snapshot;}else if(data?.version===1&&data.state)snapshot=data;else fail('This is not an Abyssals save file.');validateTransferSnapshot(snapshot,options);return {snapshot,gameVersion:data.gameVersion||'Earlier build'};}
export function saveFileName(snapshot){const name=(snapshot.state.playerName||'Aimon').replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,40)||'Aimon';return `abyssals-${name}-${new Date().toISOString().slice(0,10)}.json`;}
